import 'dart:async';
import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:path_provider/path_provider.dart';

import '../../core/failure.dart';
import '../../core/gitlab_api.dart';
import '../shell/build_info.dart';
import 'app_update.dart';

/// What the installer did with a downloaded APK.
enum InstallStart { started, needsPermission, invalid, unavailable }

/// The flavor's native AppUpdateChannel (generated by tool/bootstrap.py).
abstract interface class UpdatePlatform {
  Future<InstallStart> installApk(String path);
  Future<({bool available, int? versionCode, bool downloaded})> checkPlay();
  Future<bool> startPlayUpdate();
  Future<void> completePlayUpdate();
}

final class MethodChannelUpdatePlatform implements UpdatePlatform {
  const MethodChannelUpdatePlatform();
  static const _channel = MethodChannel('io.gitlabmobile/app_update');

  @override
  Future<InstallStart> installApk(String path) async {
    final result = await _channel.invokeMethod<String>('installApk', {'path': path});
    return InstallStart.values.asNameMap()[result] ?? InstallStart.unavailable;
  }

  @override
  Future<({bool available, int? versionCode, bool downloaded})> checkPlay() async {
    final result = await _channel.invokeMapMethod<String, Object?>('checkPlay') ?? const {};
    final code = result['versionCode'];
    return (
      available: result['available'] == true,
      versionCode: code is int ? code : null,
      downloaded: result['downloaded'] == true,
    );
  }

  @override
  Future<bool> startPlayUpdate() async => await _channel.invokeMethod<bool>('startPlayUpdate') ?? false;

  @override
  Future<void> completePlayUpdate() => _channel.invokeMethod<bool>('completePlayUpdate');
}

/// Whether the app looks for an update when it starts. A device preference,
/// not account data.
abstract interface class UpdatePreferenceStore {
  Future<String?> read();
  Future<void> write(String value);
}

/// Stored through `flutter_secure_storage` like the appearance: `1` or `0`.
final class SecureUpdatePreferenceStore implements UpdatePreferenceStore {
  SecureUpdatePreferenceStore([FlutterSecureStorage? storage])
    : _storage = storage ??
          const FlutterSecureStorage(
            aOptions: AndroidOptions(),
            iOptions: IOSOptions(accessibility: KeychainAccessibility.unlocked_this_device),
          );
  final FlutterSecureStorage _storage;
  static const key = 'gitlab_mobile_update_check_v1';
  @override
  Future<String?> read() => _storage.read(key: key);
  @override
  Future<void> write(String value) => _storage.write(key: key, value: value);
}

enum UpdateStage { idle, checking, upToDate, available, downloading, downloaded, installing, failed }

Future<Directory> defaultUpdateDirectory() async =>
    Directory('${(await getTemporaryDirectory()).path}/updates');

/// The update flow for this build's channel. The gitlab channel checks this
/// project's releases anonymously, downloads and verifies the APK and hands it
/// to the system installer; the play channel asks Google Play. Nothing happens
/// on [UpdateChannel.none].
class AppUpdateController extends ChangeNotifier {
  AppUpdateController({
    required this.channel,
    required UpdatePreferenceStore store,
    BuildInfoLoader buildInfo = loadBuildInfo,
    GitLabApi Function()? api,
    UpdatePlatform platform = const MethodChannelUpdatePlatform(),
    Future<Directory> Function() directory = defaultUpdateDirectory,
  }) : _store = store,
       _buildInfo = buildInfo,
       _apiFactory = api,
       _platform = platform,
       _directory = directory;

  final UpdateChannel channel;
  final UpdatePreferenceStore _store;
  final BuildInfoLoader _buildInfo;
  final GitLabApi Function()? _apiFactory;
  final UpdatePlatform _platform;
  final Future<Directory> Function() _directory;

  UpdateStage stage = UpdateStage.idle;
  bool autoCheck = true;
  AppRelease? release;
  int? playVersionCode;
  int? currentCode;
  ApiFailure? failure;
  (int received, int? total)? progress;

  /// Set when the last install attempt sent the user to allow installs from
  /// this app; they come back and tap 安裝 again.
  bool needsPermission = false;

  /// An update found by the check at start, not yet pointed out to the user.
  bool unannounced = false;

  GitLabApi? _api;
  File? _apk;
  Completer<void>? _cancel;
  int _epoch = 0;
  bool _disposed = false;

  bool get enabled => channel != UpdateChannel.none;
  bool get busy => const {UpdateStage.checking, UpdateStage.downloading, UpdateStage.installing}.contains(stage);

  GitLabApi get _client => _api ??= (_apiFactory ?? () => throw StateError('no update API'))();

  void _set(void Function() change) {
    if (_disposed) return;
    change();
    notifyListeners();
  }

  /// Reads the preference, removes an APK an earlier update left behind and,
  /// when the preference allows, looks for an update once.
  Future<void> start() async {
    if (!enabled) return;
    final stored = await _store.read();
    _set(() => autoCheck = stored != '0');
    if (channel == UpdateChannel.gitlab) await clearUpdateDirectory(await _directory());
    if (autoCheck) await check(announce: true);
  }

  Future<void> setAutoCheck(bool value) async {
    _set(() => autoCheck = value);
    await _store.write(value ? '1' : '0');
  }

  Future<void> check({bool announce = false}) async {
    if (!enabled || busy) return;
    final epoch = ++_epoch;
    _set(() {
      stage = UpdateStage.checking;
      failure = null;
      needsPermission = false;
    });
    try {
      final info = await _buildInfo();
      final current = int.tryParse(info.buildNumber);
      if (channel == UpdateChannel.play) {
        final play = await _platform.checkPlay();
        if (epoch != _epoch) return;
        _set(() {
          currentCode = current;
          playVersionCode = play.versionCode;
          stage = play.downloaded
              ? UpdateStage.downloaded
              : play.available ? UpdateStage.available : UpdateStage.upToDate;
          unannounced = announce && stage == UpdateStage.available;
        });
        return;
      }
      final latest = await latestAppRelease(_client, isCurrent: () => epoch == _epoch && !_disposed);
      if (epoch != _epoch) return;
      final newer = latest != null && current != null && latest.versionCode > current;
      _set(() {
        currentCode = current;
        release = newer ? latest : null;
        stage = newer ? UpdateStage.available : UpdateStage.upToDate;
        unannounced = announce && newer;
      });
    } catch (error) {
      if (epoch != _epoch) return;
      _set(() {
        failure = safeFailure(error);
        stage = UpdateStage.failed;
      });
    }
  }

  void markAnnounced() => _set(() => unannounced = false);

  /// gitlab: downloads and verifies the APK, then offers the install. play:
  /// starts Google Play's flexible update.
  Future<void> download() async {
    if (busy) return;
    if (channel == UpdateChannel.play) {
      final epoch = ++_epoch;
      _set(() => stage = UpdateStage.downloading);
      try {
        final started = await _platform.startPlayUpdate();
        if (epoch != _epoch) return;
        _set(() => stage = started ? UpdateStage.downloading : UpdateStage.available);
      } catch (error) {
        if (epoch == _epoch) _set(() { failure = safeFailure(error); stage = UpdateStage.failed; });
      }
      return;
    }
    final target = release;
    if (target == null) return;
    final epoch = ++_epoch;
    final cancel = _cancel = Completer<void>();
    _set(() {
      stage = UpdateStage.downloading;
      progress = (0, target.file.size);
      failure = null;
    });
    try {
      final apk = await downloadAppRelease(_client, target, await _directory(),
        cancel: cancel.future,
        onProgress: (received, total) {
          if (epoch == _epoch) _set(() => progress = (received, total ?? target.file.size));
        });
      if (epoch != _epoch) return;
      _apk = apk;
      _set(() => stage = UpdateStage.downloaded);
    } catch (error) {
      if (epoch != _epoch) return;
      final failed = safeFailure(error);
      _set(() {
        failure = failed.kind == FailureKind.cancelled ? null : failed;
        stage = failed.kind == FailureKind.cancelled ? UpdateStage.available : UpdateStage.failed;
      });
    }
  }

  void cancelDownload() {
    final cancel = _cancel;
    if (cancel != null && !cancel.isCompleted) cancel.complete();
  }

  /// Hands the verified APK to the system installer (gitlab), or restarts into
  /// the update Google Play downloaded (play).
  Future<void> install() async {
    if (channel == UpdateChannel.play) {
      await _platform.completePlayUpdate();
      return;
    }
    final apk = _apk;
    if (apk == null || stage != UpdateStage.downloaded) return;
    _set(() => stage = UpdateStage.installing);
    try {
      final result = await _platform.installApk(apk.path);
      _set(() {
        needsPermission = result == InstallStart.needsPermission;
        stage = UpdateStage.downloaded;
        if (result == InstallStart.invalid || result == InstallStart.unavailable) {
          failure = const ApiFailure(FailureKind.unsupported, title: '無法開啟安裝程式',
            detail: '這台裝置沒有可以安裝 APK 的程式，或更新檔已被清除。請重新下載。');
          stage = UpdateStage.failed;
        }
      });
    } catch (error) {
      _set(() {
        failure = safeFailure(error);
        stage = UpdateStage.failed;
      });
    }
  }

  @override
  void dispose() {
    _disposed = true;
    _epoch++;
    cancelDownload();
    _api?.close();
    super.dispose();
  }
}
